      codeSecteurActivite: '',
      codeSecteurActiviteSec: '',
      activiteType: '',
      codeTitre: CodeTitre.aa,
      numDom: NaN,
      dateDom: null,
      numDepot: NaN,
      dateDepot: null,
      numeroDossier: '',
      numeroDemande: '',
      numContratCom: '',
      dateContratCom: null,
      codeDevise:'',
      mntDvsPtfnFact: NaN,
      mntDvsFobFact: NaN,
      mntTndFob: NaN,
      mntTndPtfn: NaN,
      acompte: NaN,
      nomFournisseur: '',
      adrFournisseur: '',
      nomClient: '',
      adrClient: '',
      codPayAch: NaN,
      codPayProv: NaN,
      codPayOrig: NaN,
      libPaysOrig: '',
      libPaysAch:'',
      libPaysProv:'',
      libPaysDestDef:'',
      codePaysDestDef: NaN,
      codeModLiv: NaN,
      codeModReg: NaN,
      codeDelReg: NaN,
      regimeStat: NaN,
      nbrColis: NaN,
      typeAccordBct: '',
      numAccordBct: '',
